 * Находит TextDisplay с ником правильного незнакомца и подсвечивает его сундук.
 * Сундук находится левее НПС на 1 блок и ближе к игроку на 1 блок.
 */
object ThreeWeirdosChest {
    private val mc = Minecraft.getInstance()
    private var correctStrangerName: String? = null
    private var correctStrangerPos: BlockPos? = null
    private var lastChestPos: BlockPos? = null

    fun init() {
        RenderEvents.register { context ->
            if (!StarredHeltix.feature.dungeons.solvers.threeWeirdos) {
                lastChestPos = null
                return@register
            }
            if (!DungeonDetector.isInDungeon()) {
                lastChestPos = null
                return@register
            }

            val player = mc.player ?: return@register
            val level = mc.level ?: return@register

            // Ищем TextDisplay с именем правильного незнакомца
            if (correctStrangerName == null) {
                // Пытаемся получить имя из ThreeWeirdos
                correctStrangerName = ThreeWeirdos.getCorrectStranger()
            }

            if (correctStrangerName == null) {
                lastChestPos = null
                return@register
            }

            // Ищем НПС (TextDisplay) с именем незнакомца
            for (entity in level.entitiesForRendering()) {
                val displays = MobHeadDisplayDetector.getHeadDisplays(entity)
                for (comp in displays.textDisplays) {
                    val text = comp.string.replace(Regex("(?i)§[0-9a-fk-orlnmxz]"), "").trim()
                    if (text.equals(correctStrangerName, ignoreCase = true)) {
                        correctStrangerPos = entity.blockPosition()
                        break
                    }
                }
            }

            if (correctStrangerPos == null) {
                lastChestPos = null
                return@register
            }

            // Вычисляем позицию сундука: левее на 1 блок и ближе к игроку на 1 блок
            val npcPos = correctStrangerPos!!
            val playerPos = player.blockPosition()

            // Направление от НПС к игроку
            val dx = playerPos.x - npcPos.x
            val dz = playerPos.z - npcPos.z

            // Сундук левее (перпендикулярно направлению к игроку) и ближе к игроку
            // "Левее" = поворот на 90 градусов против часовой стрелки
            val leftX = -dz
            val leftZ = dx

            val chestPos = BlockPos(
