private fun advanceStage() {
    when (inputStage) {
        0 -> {
            if (newIcon.isNotBlank()) inputStage = 1
        }
        1 -> {
            if (newCommand.isNotBlank()) inputStage = 2
        }
        2 -> {
            if (buttons.size < InventoryButton.MAX_TABS) {
                val nextIndex = (buttons.maxOfOrNull { it.index } ?: -1) + 1
                val newBtn = InventoryButton(nextIndex, newIcon.trim(), newCommand.trim(), newTooltip.trim())
                val list = buttons.toMutableList()
                list.add(newBtn)
                InventoryButtonsManager.setButtons(list)
            }
            isAdding = false
            inputStage = 0
            newIcon = ""
            newCommand = ""
            newTooltip = ""
        }
    }
}

private fun moveButton(index: Int, direction: Int) {
    val list = buttons.toMutableList()
    val target = index + direction
    if (target < 0 || target >= list.size) return
    val temp = list[index]
    list[index] = list[target]
    list[target] = temp
    list.forEachIndexed { i, b -> b.index = i }
    InventoryButtonsManager.setButtons(list)
}

private fun removeButton(index: Int) {
    val list = buttons.toMutableList()
    if (index in list.indices) {
        list.removeAt(index)
        list.forEachIndexed { i, b -> b.index = i }
        InventoryButtonsManager.setButtons(list)
    }
}

